mapper.select:
SELECT GREATEST(
	COALESCE(MAX(CAST(activity_store AS SIGNED) - CAST(COALESCE(sales_store, 0) AS SIGNED)), 0),
	0)
FROM promotions_seckill_rel_goods
WHERE company_id = #{companyId}
  AND item_id = #{itemId}
  AND seckill_id = #{seckillActivityId}
  AND (disabled = 0 OR disabled IS NULL)
  AND activity_release_time <= #{nowSeconds}
  AND activity_end_time >= #{nowSeconds}
